// Review the single responder, contact allowlist and credentials before enabling.
const ENABLED = false;
const PLANNER_WORKFLOW_ID = 'REVIEW_REQUIRED';
if (!ENABLED) throw new Error('Piloto desativado.');
if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/.test(PLANNER_WORKFLOW_ID) || PLANNER_WORKFLOW_ID.startsWith('REVIEW_')) throw new Error('Configurar o planner revisado antes de consultar referencias.');
return [{json:{planner_workflow_id:PLANNER_WORKFLOW_ID}}];

const sources = $json.sources;
if (!Array.isArray(sources) || sources.length > 50) throw new Error('Referencias persistidas invalidas.');
const seen = new Set();
const items = [];
for (const row of sources) {
  if (!row || typeof row !== 'object' || Array.isArray(row) || Object.keys(row).sort().join(',') !== 'external_message_id,instance' || typeof row.instance !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9_.-]{0,79}$/.test(row.instance) || typeof row.external_message_id !== 'string' || !/^[!-~]{1,1024}$/.test(row.external_message_id)) throw new Error('Referencia persistida invalida.');
  const key = JSON.stringify([row.instance,row.external_message_id]);
  if (seen.has(key)) continue;
  seen.add(key);
  items.push({json:{instance:row.instance,external_message_id:row.external_message_id}});
}
return items;
